    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))

    cnt_a = Counter(a)
    cnt_b = Counter(b)

    if cnt_a != cnt_b:
        return "-1\n"

    # If all initial positions are the same
    unique_a = set(a)
    unique_b = set(b)

    if len(unique_a) < 2:
        # Cannot generate different positions
        if len(unique_b) < 2:
            return "0\n"
        else:
            return "-1\n"

    # Greedy matching strategy
    operations = []

    while True:
        # Check if all targets are satisfied
        all_done = True
        for tp in unique_b:
            if tp not in a:
                all_done = False
                break

        if all_done:
            break

        # Need to generate at least one target position that's missing
        need = None
        for tp in unique_b:
            if tp not in a:
                need = tp
                break

        # Try to generate 'need' using existing positions
        # 2 * y - x = need, so x = 2 * y - need
        found = False
        for y in a:
            for x in a:
                if x == y:
                    continue
                # Generate new position
                new_pos = 2 * y - x

                if new_pos == need:
                    # Record operation
                    operations.append((x, y, new_pos))

                    # Move one stone from x to new_pos
                    # Remove x, add new_pos
                    removed_idx = None
                    for i in range(len(a)):
                        if a[i] == x:
                            removed_idx = i
                            break
                    if removed_idx is not None:
                        a.pop(removed_idx)
                        a.append(new_pos)

                    found = True
                    break
            if found:
                break

        if not found:
