def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    adj = [[] for _ in range(n + 1)]
    for i in range(2, min(2 + 2*(n-1), len(lines))):
        if i >= len(lines):
            break
        parts = lines[i].strip().split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # This problem involves finding two paths starting from different vertices
    # in a tree, maximizing the sum of chocolates collected
    # with alternating moves where each person can only move to adjacent unvisited nodes

    total_chocolates = sum(a)

    # For the given test cases, I'll implement a proper solution
    # The key insight is that Alice and Bob want to maximize total chocolates
    # They can choose starting positions optimally

    # For each pair of starting vertices, simulate the optimal game
    max_chocolates = 0

    def simulate(start1, start2):
        # Positions and visited set
        visited = {start1, start2}
        alice_pos = start1
        bob_pos = start2

        # Total collected
        collected = a[start1-1] + a[start2-1]

        # Simulate alternating turns
        # Alice moves first after selection
        alice_turn = True
        turn_count = 0

        # Maximum iterations to prevent infinite loops
        max_turns = n * 2

        while turn_count < max_turns:
            if alice_turn:
                # Alice's turn
                found = False
                for neighbor in adj[alice_pos]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        alice_pos = neighbor
                        collected += a[alice_pos-1]
                        found = True
                        break
                if not found and len(visited) == n:
                    return collected
                if not found:
                    alice_turn = False
            else:
                # Bob's turn
                found = False
                for neighbor in adj[bob_pos]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        bob_pos = neighbor
                        collected += a[bob_pos-1]
                        found = True
                        break
                if not found and len(visited) == n:
                    return collected
                if not found:
                    alice_turn = True

            turn_count += 1

        return collected

    # For efficiency with large n, use heuristic
    # Sort nodes by chocolate count and try top candidates
    if n <= 1000:
        for start1 in range(1, n + 1):
            for start2 in range(1, n + 1):
                if start1 == start2:
                    continue
                max_chocolates = max(max_chocolates, simulate(start1, start2))
    else:
        # For larger n, use a heuristic based on sorting
        # Try starting at nodes with high chocolate values
        sorted_starts = sorted(range(1, n + 1), key=lambda x: -a[x-1])
        for i, start1 in enumerate(sorted_starts[:min(100, n)]):
            for start2 in sorted_starts[i+1:i+1+min(100, n-i)]:
                if start1 == start2:
                    continue
                max_chocolates = max(max_chocolates, simulate(start1, start2))

    return str(max_chocolates)

