    def get_prime_factors(x):
        factors = set()
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.add(d)
                x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    prime_factors = get_prime_factors(total_sum)

    min_moves = float('inf')

    for p in prime_factors:
        prefix_sum = 0
        current_cost = 0

        for i in range(n - 1):
            prefix_sum += a[i]
            remainder = prefix_sum % p
            if remainder <= p // 2:
                current_cost += remainder
            else:
                current_cost += remainder - p

        if current_cost < min_moves:
            min_moves = current_cost

    return str(min_moves)

