        """Check if seq is a geometric progression"""
        length = len(seq)

        # Sequences of length 0, 1, 2 are always GPs
        if length <= 2:
            return True

        # All zeros is a GP (trivial)
        if all(x == 0 for x in seq):
            return True

        # If first element is 0 but not all, can't be GP
        if seq[0] == 0:
            return False

        # Check GP property using cross-multiplication:
        # For GP: seq[i] * seq[i+2] == (seq[i+1])^2
        for i in range(length - 2):
            if seq[i] * seq[i+2] != (seq[i+1] * seq[i+1]):
                return False

        return True

    # Check if original sequence is already a GP
    if is_gp(sequence):
        return "0\n"

    # Try removing each element and check if result is a GP
    for i in range(len(sequence)):
        new_seq = sequence[:i] + sequence[i+1:]
        if is_gp(new_seq):
            return "1\n"

    # If neither works
    return "2\n"

