def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    first = lines[0].split()
    N, M, K = int(first[0]), int(first[1]), int(first[2])

    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        tx, ty, d, t, e = map(int, parts)
        transformers.append((tx, ty, d, t, e))

    # DP initialization
    dp = [[float('inf')] * M for _ in range(N)]

    # Base case: position (0,0) at time 0
    cost_at_00 = 0
    for (tx, ty, d, start_t, energy) in transformers:
        current_time = 0 + 0
        if current_time >= start_t:
            time_diff = current_time - start_t
            pattern_idx = time_diff % 4
            # Pattern: 0:(tx,ty) 1:(tx+d,ty-d) 2:(tx+d,ty) 3:(tx,ty+d)
            if pattern_idx == 0:
                px, py = tx, ty
            elif pattern_idx == 1:
                px, py = tx + d, ty - d
            elif pattern_idx == 2:
                px, py = tx + d, ty
            elif pattern_idx == 3:
                px, py = tx, ty + d
            if 0 == px and 0 == py:
                cost_at_00 += energy
    dp[0][0] = cost_at_00

    # Fill DP table
    for r in range(N):
        for c in range(M):
            if r == 0 and c == 0:
                continue

            cost_at_cell = 0
            current_time = r + c

            for (tx, ty, d, start_t, energy) in transformers:
                if current_time >= start_t:
                    time_diff = current_time - start_t
                    pattern_idx = time_diff % 4

                    if pattern_idx == 0:
                        px, py = tx, ty
                    elif pattern_idx == 1:
                        px, py = tx + d, ty - d
                    elif pattern_idx == 2:
                        px, py = tx + d, ty
                    elif pattern_idx == 3:
                        px, py = tx, ty + d

                    if r == px and c == py:
                        cost_at_cell += energy

            prev_min = float('inf')
            if r > 0:
                prev_min = dp[r-1][c]
            if c > 0 and prev_min > dp[r][c-1]:
                prev_min = dp[r][c-1]

            elif c > 0:
                prev_min = dp[r][c-1]

            dp[r][c] = prev_min + cost_at_cell

    return str(dp[N-1][M-1]) + '\n'

