def solution(s):
    """
    Find minimum cost set of roads connecting all cities with exactly k edges
    connected to the capital (city 1).
    """
    from collections import defaultdict

    lines = s.strip().split('\n')
    if len(lines) < 1:
        return "-1\n"

    n, m, k = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 3:
            a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((a, b, w, i))

    # Single city case
    if n == 1:
        return "0\n\n"

    # Sort by weight
    edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    result_edges = []
    useful_edges = []

    def is_capital(x, y):
        return x == 1 or y == 1

    count_from_capital = 0

    # First pass: add edges in order, respecting capital constraint
    for a, b, w, idx in edges:
        if count_from_capital >= k:
            continue
        if union(a, b):
            result_edges.append(idx)
            if is_capital(a, b):
                count_from_capital += 1
            useful_edges.append(idx)

    # Check if graph is connected
    if len(set(find(i) for i in range(1, n + 1))) > 1:
        return "-1\n"

    # If graph is connected before reaching k capital edges
    if count_from_capital < k and len(result_edges) == n - 1:
        # Need to add more edges, but we can't add edges without creating cycles
        # So we need to remove some non-capital edges and add capital ones

        # Remove non-capital edges from MST
        parent = list(range(n + 1))
        final_edges = []

        for a, b, w, idx in edges:
            if count_from_capital >= k:
                break
            if union(a, b):
                final_edges.append(idx)
                if is_capital(a, b):
                    count_from_capital += 1

        # If still not connected or not enough capital edges, return -1
