import sys

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, capacity, _ in self.graph[u]:
                if capacity > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, capacity, reverse_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and capacity > 0:
                pushed = self.dfs(v, t, min(flow, capacity), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][reverse_idx][1] += pushed
                    return pushed
        return 0

    def min_cut(self, s, t):
        max_flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_flow += pushed
        return max_flow

