    lines = data.strip().split('\n')
    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(m):
        l, r, x, c = map(int, lines[i+1].split())
        restrictions.append((l, r, x, c))

    # Build flow network for min-cut
    # Nodes: S=0, T=1, u_{i,k}=2+(i-1)*h+(k-1) for position i, level k
    #        R_j=2+n*h+j for restriction j

    num_nodes = 2 + n * h + m
    S, T = 0, 1
    dinic = Dinic(num_nodes)

    total_profit = 0
    for i in range(1, n+1):
        for k in range(1, h+1):
            u = 2 + (i-1)*h + (k-1)
            capacity = 2 * k - 1  # marginal profit for height k
            dinic.add_edge(S, u, capacity)
            total_profit += capacity

    # Monotonicity: if height >= k+1 then height >= k
    for i in range(1, n+1):
        for k in range(1, h):
            u_k = 2 + (i-1)*h + (k-1)
            u_k1 = 2 + (i-1)*h + k
            dinic.add_edge(u_k, u_k1, float('inf'))

    # Restriction nodes and edges
    for j in range(m):
        l, r, x, c_val = restrictions[j]
        R = 2 + n * h + j

        # If any house in [l,r] has height > x (>= x+1), pay fine c
        for i in range(l, r+1):
            for k in range(x+1, h+1):
                u = 2 + (i-1)*h + (k-1)
                dinic.add_edge(u, R, float('inf'))

        dinic.add_edge(R, T, c_val)

    min_cut = dinic.min_cut(S, T)
    return str(total_profit - min_cut)

