            if last[x] <= first[next_x] - 1:
                consecutive = 0
                if last[x] - first[x] - 1 == 0:
                    consecutive = 1
            if last[x] >= first[x] + 1:
                consecutive += 1
                max_consecutive = max(max_consecutive, consecutive)

    return max_consecutive

