def square_free_part(n):
    if n == 0:
        return 0
    result = 1
    divisor = 2
    temp = n
    while divisor * divisor <= temp:
        count = 0
        while temp % divisor == 0:
            count += 1
            temp //= divisor
        if count % 2 == 1:
            result *= divisor
        divisor += 1
    if temp > 1:
        result *= temp
    return result

