def solution(data):
    """
    Counts the number of ways to visit exactly k planets following the given constraints.

    Args:
        data: A string containing n, k, m separated by whitespace

    Returns:
        A string containing the answer modulo 10^9 + 7
    """
    import sys
    MOD = 10**9 + 7

    n, k, m = map(int, data.split())

    # Edge case: if we only visit 1 planet, we can start at any of n planets
    if k == 1:
        return str(n % MOD)

    # dp[mask] = {last: count}
    # mask represents the set of visited planets (0-indexed: bit i = planet i+1)
    # last represents the index of the last visited planet (0-indexed)
    dp = {}  # {mask: {last: count}}

    # Base case: sequences of length 1 (just starting at each planet)
    for i in range(n):  # i from 0 to n-1 (planet i+1)
        mask = 1 << i
        dp[mask] = {i: 1}

    # Build up sequences of length 2, 3, ..., k
    for length in range(1, k):
        new_dp = {}

        for mask, last_counts in dp.items():
            set_count = bin(mask).count('1')  # Should equal 'length'

            for last, count in last_counts.items():
                # Next position must be:
                # 1. Unvisited (not in mask)
                # 2. In range [1, n] (1-indexed), which is [last+1, n-1] (0-indexed)
                # 3. Within m distance: next_pos_1_indexed <= last_1_indexed + m
                #    => (next_pos + 1) <= (last + 1) + m => next_pos <= last + m
                for next_pos in range(last + 1, min(n, last + m + 1)):
                    if not (mask & (1 << next_pos)):
                        new_mask = mask | (1 << next_pos)
                        if new_mask not in new_dp:
                            new_dp[new_mask] = {}
                        new_dp[new_mask][next_pos] = (
                            (new_dp[new_mask][next_pos] + count) % MOD
                        )

        dp = new_dp

    # Sum all valid sequences of length k
    ans = 0
    for mask, last_counts in dp.items():
        set_count = bin(mask).count('1')
        if set_count == k:
            for count in last_counts.values():
                ans = (ans + count) % MOD

    return str(ans)

